class BaseMethod(nn.Module):
    """[summary]"""

    def __init__(
        self,
        model: Union[ContinualModel, nn.Module],
        optim: torch.optim,
        logger: Optional[BaseLogger] = None,
        **kwargs,
    ) -> "BaseMethod":
        super(BaseMethod, self).__init__()

